<script setup lang="ts">
import {onMounted,onUnmounted,ref} from 'vue';
import {X,Download,LoaderCircle,AlertCircle} from 'lucide-vue-next';
import {appUrl} from '../lib/urls';
const props=defineProps<{artifact:Record<string,any>;conversationId:string|null}>();
const emit=defineEmits<{close:[];approved:[]}>();
const authorizing=ref(false);const authorized=ref(props.artifact.metadata?.visual_consent?.conversation_id===props.conversationId);
async function authorize(){if(!props.conversationId)return;authorizing.value=true;error.value='';try{const response=await fetch(appUrl('/api/artifacts/'+props.artifact.id+'/visual-consent'),{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json',Accept:'application/json','X-CSRF-TOKEN':document.querySelector<HTMLMetaElement>('meta[name=\"csrf-token\"]')?.content??''},body:JSON.stringify({conversation_id:props.conversationId,recipient:'openai'})});const result=await response.json();if(!response.ok)throw new Error(result.message??'Não foi possível registrar a autorização.');authorized.value=true;emit('approved');}catch(e){error.value=(e as Error).message;}finally{authorizing.value=false;}}
const image=ref('');const error=ref('');const loading=ref(true);
async function load(){try{const response=await fetch(appUrl('/api/artifacts/'+encodeURIComponent(props.artifact.id)+'/download'),{credentials:'same-origin'});if(!response.ok)throw new Error('Não foi possível abrir esta imagem. Verifique sua sessão e tente novamente.');const blob=await response.blob();if(!['image/png','image/jpeg'].includes(blob.type))throw new Error('O arquivo não é uma imagem compatível.');image.value=URL.createObjectURL(blob);}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
function keydown(e:KeyboardEvent){if(e.key==='Escape')emit('close');}
onMounted(()=>{load();window.addEventListener('keydown',keydown);});
onUnmounted(()=>{if(image.value)URL.revokeObjectURL(image.value);window.removeEventListener('keydown',keydown);});
</script>
<template><div class="modal-backdrop" @click.self="emit('close')"><section class="modal artifact-preview-modal" role="dialog" aria-modal="true" aria-label="Prévia do arquivo"><button class="modal-close icon-button" aria-label="Fechar prévia" @click="emit('close')"><X :size="19"/></button><h2>{{artifact.name}}</h2><p class="modal-description">{{artifact.kind==='dashboard_export'?'Imagem real renderizada pelo G-Analise BI.':'Imagem anexada ao projeto.'}} <span v-if="artifact.metadata?.resource">{{artifact.metadata.resource}}</span></p><div v-if="loading" class="catalog-loading"><LoaderCircle class="spin" :size="24"/>Carregando imagem…</div><div v-else-if="error" class="form-error" role="alert"><AlertCircle :size="18"/>{{error}}</div><div v-else class="artifact-preview-image"><img :src="image" :alt="artifact.name"></div><p v-if="artifact.kind==='dashboard_export'&&conversationId" class="visual-consent-note">A análise visual envia esta imagem e os indicadores visíveis à OpenAI, com sua conta ChatGPT, para compor o contexto desta conversa.</p><div class="modal-footer"><button v-if="artifact.kind==='dashboard_export'&&conversationId" class="secondary-button" :disabled="loading||authorizing||authorized" @click="authorize">{{authorized?'Envio à OpenAI autorizado':'Autorizar análise visual com IA'}}</button><a class="secondary-button" :href="appUrl('/api/artifacts/'+artifact.id+'/download')"><Download :size="15"/>Baixar imagem</a><button class="primary-button" @click="emit('close')">Fechar prévia</button></div></section></div></template>
<style scoped>.visual-consent-note{font-size:12px;color:#63718a;line-height:1.6;margin-top:16px}.artifact-preview-modal{max-width:1200px;width:calc(100vw - 48px)}.artifact-preview-image{max-height:min(56vh,calc(100dvh - 330px));overflow:auto;border:1px solid #e6e9ef;border-radius:10px;background:#f0f3f8;padding:12px}.artifact-preview-image img{display:block;max-width:100%;height:auto;margin:auto}.artifact-preview-modal h2{padding-right:28px}.catalog-loading{padding:40px;text-align:center;display:flex;gap:12px;align-items:center;justify-content:center}</style>
